    DatabaseCore::GetStatement(
        "UpdateThreadInfo"_ns,
        "UPDATE messages SET threadId = :threadId, threadParent = :threadParent WHERE id = :id"_ns,
        getter_AddRefs(mStmt));
    mStmt->NewBindingParamsArray(getter_AddRefs(mParamsArray));

